// Saved patch identity is independent of navigation and visual display choices.
let savedPatches=[];try{savedPatches=JSON.parse(localStorage.getItem('motherbox-library')||'[]')}catch{}
state.bpm=state.bpm||120;state.sync=state.sync!==false;state.volume=state.volume??45;state.softclip=state.softclip!==false;
function restoreGlobals(){$('#bpm').value=state.bpm;$('#volume').value=state.volume;$('#softclip').checked=state.softclip;$('#sync').classList.toggle('selected',state.sync);$('#sync').textContent=state.sync?'SYNC':'FREE';updateVolume()}
restoreGlobals();
function patchSignature(){return JSON.stringify({gens:state.gens,macros:state.macros,routes:state.routes,bass:state.bass,bpm:state.bpm,sync:state.sync,volume:state.volume,softclip:state.softclip})}
let cleanSignature=state.cleanSignature||patchSignature();
function updatePatchIdentity(){const modified=patchSignature()!==cleanSignature;state.modified=modified;const title=state.patchTitle||patchDefs[state.preset][0];$('#patchName').replaceChildren(document.createTextNode(title+(modified?' *':'')),Object.assign(document.createElement('span'),{textContent:state.savedId?' / USER':' / 0'+(state.preset+1)}));$('#patchName').classList.toggle('modified',modified);$('#patchStatus').textContent=modified?'MODIFIED · SAVE PATCH':'SAVED';$('#patchStatus').classList.toggle('modified',modified);$('#save').setAttribute('aria-label',modified?'Save modified patch':'Save patch');document.body.dataset.mode=state.mode;localStorage.setItem('blackbox-patch',JSON.stringify({...state,cleanSignature}));}
const engineRender=render;render=function(){engineRender();updatePatchIdentity();renderUserPatches()};
const factoryRoutes=[{from:0,to:1,depth:30,lag:10,bipolar:true},{from:2,to:0,depth:24,lag:5,bipolar:true},{from:1,to:3,depth:40,lag:0,bipolar:false},{from:3,to:4,depth:38,lag:20,bipolar:true},{from:0,to:2,depth:20,lag:10,bipolar:true},{from:4,to:0,depth:15,lag:15,bipolar:false}];
const engineLoad=loadPreset;loadPreset=function(i){state.patchTitle=null;state.savedId=null;state.gens=types.map((type,j)=>({type,name:['Lorenz attractor','Euclidean rhythm','Quadrature LFO','Custom waveform','Sub oscillator'][j],params:[...defaults[j]],muted:false,algorithm:'Lorenz'}));state.selected=Math.min(state.selected,4);state.routes=structuredClone(factoryRoutes);state.bpm=120;state.sync=true;state.volume=45;state.softclip=true;restoreGlobals();engineLoad(i);cleanSignature=patchSignature();updatePatchIdentity();renderUserPatches()};
function renderUserPatches(){const holder=$('#userPresets');holder.replaceChildren();savedPatches.forEach(p=>{const b=document.createElement('button');b.textContent=p.name;b.classList.toggle('active',state.savedId===p.id);b.onclick=()=>{const mode=state.mode;state={...structuredClone(p.patch),mode,savedId:p.id,patchTitle:p.name};restoreGlobals();cleanSignature=patchSignature();render();toast('Loaded '+p.name)};holder.appendChild(b)})}
document.addEventListener('input',e=>{if(e.target.closest('#saveDialog'))return;if(e.target.id==='bpm'){state.bpm=Math.max(30,Math.min(240,+e.target.value||120));tempo=state.sync?state.bpm/120:1}if(e.target.id==='volume')state.volume=+e.target.value;if(e.target.id==='softclip')state.softclip=e.target.checked;updatePatchIdentity()});
document.addEventListener('change',e=>{if(!e.target.closest('#saveDialog'))updatePatchIdentity()});
document.addEventListener('click',e=>{if(e.target.closest('#saveDialog'))return;if(e.target.closest('#sync')){state.sync=$('#sync').classList.contains('selected');tempo=state.sync?state.bpm/120:1}updatePatchIdentity()});
$('#save').onclick=()=>{$('#patchTitle').value=state.patchTitle||patchDefs[state.preset][0];$('#saveDialog').showModal();$('#patchTitle').focus();$('#patchTitle').select()};
$('#cancelSave').onclick=()=>$('#saveDialog').close();
$('#saveForm').onsubmit=e=>{e.preventDefault();const name=$('#patchTitle').value.trim();if(!name)return;const id=state.savedId||'patch-'+Date.now();state.savedId=id;state.patchTitle=name;cleanSignature=patchSignature();state.cleanSignature=cleanSignature;state.modified=false;const patch=structuredClone(state),existing=savedPatches.findIndex(p=>p.id===id),entry={id,name,patch};if(existing>=0)savedPatches[existing]=entry;else savedPatches.push(entry);localStorage.setItem('motherbox-library',JSON.stringify(savedPatches));updatePatchIdentity();renderUserPatches();$('#saveDialog').close();const url=URL.createObjectURL(new Blob([JSON.stringify(patch,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Saved '+name)};
render();
